import{_ as t,o as n,c as e,a as s}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"Agent 规划能力（Planning）","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents/planning.md","filePath":"ai/agents/planning.md"}'),o={name:"ai/agents/planning.md"};function i(r,a,l,h,p,d){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="agent-规划能力-planning" tabindex="-1">Agent 规划能力（Planning） <a class="header-anchor" href="#agent-规划能力-planning" aria-label="Permalink to &quot;Agent 规划能力（Planning）&quot;">​</a></h1><h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p>本笔记是 AI Agent 开发系列笔记的第七篇，接续前六篇概述、架构设计、工具调用、多 Agent 协作、Agent 框架与记忆机制，聚焦于 Agent 规划能力这一“将抽象目标转化为可执行行动序列”的核心认知机制。如果说工具调用是 Agent 的“双手”，记忆机制是 Agent 的“心智底座”，那么多 Agent 协作是 Agent 的“社会形态”，而规划能力则是 Agent 的“理性大脑”——它决定了 Agent 能否在面对复杂任务时，像人类专家一样进行系统性的思考、推演与决策。</p><p>规划能力在 AI Agent 技术体系中占据不可替代的核心地位。这种“感知-规划-行动”的闭环架构使 Agent 能够通过访问实时数据、调用外部 API 并维持任务的长期一致性，实现复杂流程的自动化。2026 年的 S&amp;P Global 研究报告显示，58% 的企业正在积极构建 Agent 能力。Snowflake 的报告指出，2025 年行业经历了从简单聊天机器人案例向能够“规划、执行和迭代”的系统的大规模实验性跨越，企业组织开始构建能够自主计划、执行和持续迭代的智能系统。</p><p>同时，规划技术本身也正经历深刻变革。传统方法面临“粒度困境”——简单任务被过度复杂化、复杂任务则规划不足。在这一背景下，从固定粒度规划到自适应分层规划、从单体 Agent 规划到多 Agent 规划架构的转型成为技术演进的主线。ReAcTree 在 WA H-NL 基准上将目标成功率从 31%（ReAct）提升至 61%——几乎翻倍；NaviAgent 在复杂任务上带来平均 13.1 个百分点的任务成功率提升；AdaPlan-H 通过在粗粒度宏观计划基础上根据任务复杂性渐进式细化，同时缓解了过度规划与规划不足的双重问题。</p><p>本笔记将从规划能力的基本概念入手，逐层深入推理范式（CoT/ToT/GoT）、核心规划架构（ReAct/Plan-and-Execute/Reflection）、分层与双层规划、动态重规划机制、2026 年前沿创新、模型层面的技术支撑、评测基准与挑战，以及未来演进方向，力求呈现 Agent 规划技术的完整图景。</p><h2 id="二、规划能力的基本概念" tabindex="-1">二、规划能力的基本概念 <a class="header-anchor" href="#二、规划能力的基本概念" aria-label="Permalink to &quot;二、规划能力的基本概念&quot;">​</a></h2><h3 id="_2-1-定义" tabindex="-1">2.1 定义 <a class="header-anchor" href="#_2-1-定义" aria-label="Permalink to &quot;2.1 定义&quot;">​</a></h3><p>规划（Planning）在 AI Agent 语境中的定义可形式化表述为：给定初始状态 $s_0$、目标状态 $g$ 和环境转移函数 $T$，找到行动序列 $(a_1, a_2, …, a_n)$，使得在执行后，最终状态 $s_n$ 满足目标 $g$。</p><p>在大语言模型驱动的 Agent 中，规划能力体现在以下几个方面：Agent 的规划能力使其能够更好地理解任务中的长期依赖关系，并在动态环境中按正确顺序采取行动；将复杂目标拆解为可执行子任务，以旅行规划为例，可自动生成“机票预订→酒店筛选→行程安排”的子任务序列；在执行过程中根据观察反馈动态调整原计划，实现持续改进；在多步决策中保持目标导向而非迷失于局部最优。</p><p>从产业层面来看，规划能力（与记忆、工具使用和迭代推理相结合）使智能体系统能够在复杂环境中自主运行。Agentic AI 系统的核心能力被定义为长期推理、上下文感知与自适应决策。规划能力使 Agent 能够从“被动响应”走向“主动执行”，从工具调用者进化为智能决策者。</p><h3 id="_2-2-规划的-粒度困境" tabindex="-1">2.2 规划的“粒度困境” <a class="header-anchor" href="#_2-2-规划的-粒度困境" aria-label="Permalink to &quot;2.2 规划的“粒度困境”&quot;">​</a></h3><p>传统的规划方法长期面临一个基本限制：它们在固定的粒度级别上运行。具体而言，它们要么为简单任务提供过多细节（造成过度规划，overplanning），要么为复杂任务提供不足的细节（造成规划不足，underplanning），无法在简洁性和完整性之间实现最佳平衡。这一困境的根源在于：任务复杂度是一个连续光谱，而固定粒度的规划器无法自适应地调整其规划深度。</p><h3 id="_2-3-认知科学启示-人类规划的双系统" tabindex="-1">2.3 认知科学启示：人类规划的双系统 <a class="header-anchor" href="#_2-3-认知科学启示-人类规划的双系统" aria-label="Permalink to &quot;2.3 认知科学启示：人类规划的双系统&quot;">​</a></h3><p>人类的规划能力为 AI 提供了重要的认知范式。认知科学中的“渐进式细化”原则（progressive refinement）为 Agent 规划架构设计提供了灵感：</p><ul><li><strong>宏观规划阶段</strong>（Coarse-grained Planning）：快速生成一个高层次的任务骨架，类似人类在开始复杂工作前的“头脑风暴”。这一阶段关注任务的总体结构和主要里程碑，不涉及具体执行细节。</li><li><strong>微观细化阶段</strong>（Fine-grained Refinement）：根据任务的实际进展情况，在执行过程中逐步展开必要细节。当遇到简单子任务时，保持宏观层面即可；当遇到复杂子任务时，在进入该分支时进行更细致的分解和规划。</li></ul><p>这种“先粗后细”的渐进式规划策略，正是当前自适应分层规划架构的理论基础。</p><h2 id="三、推理范式-从-chain-of-thought-到-graph-of-thoughts" tabindex="-1">三、推理范式：从 Chain-of-Thought 到 Graph-of-Thoughts <a class="header-anchor" href="#三、推理范式-从-chain-of-thought-到-graph-of-thoughts" aria-label="Permalink to &quot;三、推理范式：从 Chain-of-Thought 到 Graph-of-Thoughts&quot;">​</a></h2><p>规划能力的底层依赖于 LLM 的推理能力。在传统大模型的“直觉抢答”模式中，模型在面对复杂逻辑推理时容易陷入“浅层思考”，生成看似合理但实际错误的答案。为解决这一问题，学术界提出了从“快思考”到“慢思考”的范式转型。</p><h3 id="_3-1-cot-线性推理的范式突破" tabindex="-1">3.1 CoT：线性推理的范式突破 <a class="header-anchor" href="#_3-1-cot-线性推理的范式突破" aria-label="Permalink to &quot;3.1 CoT：线性推理的范式突破&quot;">​</a></h3><p><strong>思维链（Chain of Thought, CoT）</strong> 由 Google 在 2022 年提出，其核心在于将多步骤推理过程显式化。CoT 将复杂问题拆解为可追溯的推理步骤序列，使模型能够像人类专家一样进行逐步验证和修正。</p><p><strong>技术原理</strong>：CoT 的实现包含三个关键环节——问题分解（将复杂问题拆解为子问题序列）、中间步骤生成（为每个子问题生成候选解决方案）、结果验证与迭代（通过自洽性检查排除矛盾步骤）。</p><p><strong>实践效果</strong>：Google DeepMind 的 PaLM 模型通过 CoT 技术，在数学推理任务中准确率提升 37%。在医疗领域，思维链使模型能够生成可解释的诊断路径，梅奥诊所的试点项目显示诊断效率提升 22%。</p><p><strong>局限性</strong>：CoT 采用单一线性路径进行推理，无法在多个可行路径之间进行比较和选择。当推理路径上某一步出错时，整个推理过程都会受到影响。</p><h3 id="_3-2-tot-分支推理与最优解搜索" tabindex="-1">3.2 ToT：分支推理与最优解搜索 <a class="header-anchor" href="#_3-2-tot-分支推理与最优解搜索" aria-label="Permalink to &quot;3.2 ToT：分支推理与最优解搜索&quot;">​</a></h3><p><strong>思维树（Tree of Thoughts, ToT）</strong> 通过构建多分支推理结构实现全局优化，突破 CoT 的线性限制。</p><p><strong>技术实现</strong>：状态空间建模（将问题转化为节点和边的图结构）、剪枝策略（通过蒙特卡洛树搜索动态剪除低价值分支）、价值函数设计（结合领域知识定义节点评估标准）。</p><p><strong>应用效果</strong>：以编程任务为例，思维树可同时探索递归解法和迭代解法，通过比较两种路径的复杂度选择最优方案。OpenAI 的 Codex 模型采用类似技术后，代码生成正确率从 61% 提升至 78%。微软 Azure 的 AI 调试工具显示，采用思维树架构的模型在处理模糊需求时，解决方案通过率提高 40%。</p><h3 id="_3-3-got-从树到图的推理进化" tabindex="-1">3.3 GoT：从树到图的推理进化 <a class="header-anchor" href="#_3-3-got-从树到图的推理进化" aria-label="Permalink to &quot;3.3 GoT：从树到图的推理进化&quot;">​</a></h3><p><strong>思维图（Graph of Thoughts, GoT）</strong> 将推理结构从树形升级为有向无环图。与 ToT 相比，GoT 允许节点拥有多个父节点（从树变为图），支持思维聚合和合成。Thought Graph 作为 MCP 服务器，赋予 AI Agent 非线性推理能力——思想的 DAG 结构支持分支、合并、矛盾、死路剪枝以及通过加权聚合的收敛路径。</p><p>GoT 的核心价值在于：当推理路径出现矛盾时，系统可以回溯到分歧点并聚合不同路径的结论。这种非线性结构更适合处理复杂的多跳推理和知识融合任务。</p><h3 id="_3-4-三种推理范式的对比" tabindex="-1">3.4 三种推理范式的对比 <a class="header-anchor" href="#_3-4-三种推理范式的对比" aria-label="Permalink to &quot;3.4 三种推理范式的对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>CoT（思维链）</th><th>ToT（思维树）</th><th>GoT（思维图）</th></tr></thead><tbody><tr><td>结构形态</td><td>线性链</td><td>分支树</td><td>有向无环图</td></tr><tr><td>分支处理</td><td>不支持</td><td>支持多分支并行</td><td>支持分支+合并+聚合</td></tr><tr><td>回溯能力</td><td>无</td><td>支持回溯至分支点</td><td>支持任意节点回溯</td></tr><tr><td>节点关系</td><td>单父节点</td><td>单父节点</td><td>允许多父节点</td></tr><tr><td>适用场景</td><td>简单多步推理</td><td>多解空间探索</td><td>复杂知识融合推理</td></tr><tr><td>计算开销</td><td>低</td><td>中等</td><td>高</td></tr></tbody></table><h2 id="四、核心规划架构模式" tabindex="-1">四、核心规划架构模式 <a class="header-anchor" href="#四、核心规划架构模式" aria-label="Permalink to &quot;四、核心规划架构模式&quot;">​</a></h2><p>Agent 的规划能力主要通过三种核心架构模式实现：ReAct 模式（推理-行动闭环）、Plan-and-Execute 模式（结构化规划优先）、Reflection 模式（动态反思优化）。这三种模式分别对应着不同类型的任务特征和执行需求。</p><h3 id="_4-1-react-模式-推理-行动闭环" tabindex="-1">4.1 ReAct 模式：推理-行动闭环 <a class="header-anchor" href="#_4-1-react-模式-推理-行动闭环" aria-label="Permalink to &quot;4.1 ReAct 模式：推理-行动闭环&quot;">​</a></h3><p>ReAct 由 Yao 等人于 2022 年提出，其核心创新在于将思维链（CoT）与环境交互深度融合。通过“推理→行动→观察”的迭代循环，解决传统 LLM 缺乏外部反馈的缺陷。</p><p><strong>核心架构组件</strong>：</p><ul><li><strong>推理引擎</strong>（Reasoning Engine）：基于 LLM 的思维链生成，需支持多步逻辑推导。ReAct 引擎可集成蒙特卡洛树搜索（MCTS）优化推理路径，使复杂问题求解路径缩短 35%。</li><li><strong>工具调用系统</strong>（Tool Invocation System）：集成 API 调用、数据库查询、Shell 命令等执行能力。</li><li><strong>状态管理器</strong>（State Manager）：维护任务上下文与历史交互记录，确保推理过程的连续性。</li><li><strong>反馈评估模块</strong>（Feedback Evaluation）：判断是否达到终止条件或需要重新推理。</li></ul><p><strong>执行流程</strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 简化版 ReAct 循环实现示例</span></span>
<span class="line"><span class="__shiki_1itgoe">def</span><span class="__shiki_1t8gfj"> react_loop</span><span class="__shiki_140thh">(task, llm_api):</span></span>
<span class="line"><span class="__shiki_140thh">    state </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> {</span><span class="__shiki_mdbnqw">&quot;task&quot;</span><span class="__shiki_140thh">: task, </span><span class="__shiki_mdbnqw">&quot;history&quot;</span><span class="__shiki_140thh">: []}</span></span>
<span class="line"><span class="__shiki_1itgoe">    while</span><span class="__shiki_dzsirb"> True</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_21nrsd">        # 推理阶段：分析当前状态并决定下一步行动</span></span>
<span class="line"><span class="__shiki_140thh">        reasoning </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> llm_api.generate_reasoning(state)</span></span>
<span class="line"><span class="__shiki_140thh">        state[</span><span class="__shiki_mdbnqw">&quot;history&quot;</span><span class="__shiki_140thh">].append((</span><span class="__shiki_mdbnqw">&quot;reasoning&quot;</span><span class="__shiki_140thh">, reasoning))</span></span>
<span class="line"><span class="__shiki_21nrsd">        # 行动阶段：解析工具调用并执行</span></span>
<span class="line"><span class="__shiki_140thh">        action </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> parse_action(reasoning)</span></span>
<span class="line"><span class="__shiki_1itgoe">        if</span><span class="__shiki_140thh"> action[</span><span class="__shiki_mdbnqw">&quot;type&quot;</span><span class="__shiki_140thh">] </span><span class="__shiki_1itgoe">==</span><span class="__shiki_mdbnqw"> &quot;terminate&quot;</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_1itgoe">            break</span></span>
<span class="line"><span class="__shiki_140thh">        result </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> execute_action(action)</span></span>
<span class="line"><span class="__shiki_140thh">        state[</span><span class="__shiki_mdbnqw">&quot;history&quot;</span><span class="__shiki_140thh">].append((</span><span class="__shiki_mdbnqw">&quot;action&quot;</span><span class="__shiki_140thh">, action))</span></span>
<span class="line"><span class="__shiki_21nrsd">        # 观察阶段：处理执行结果并更新状态</span></span>
<span class="line"><span class="__shiki_140thh">        observation </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> process_result(result)</span></span>
<span class="line"><span class="__shiki_140thh">        state[</span><span class="__shiki_mdbnqw">&quot;history&quot;</span><span class="__shiki_140thh">].append((</span><span class="__shiki_mdbnqw">&quot;observation&quot;</span><span class="__shiki_140thh">, observation))</span></span></code></pre></div><p><strong>典型应用场景</strong>：动态信息检索（根据中间结果调整查询策略）、复杂决策系统（如金融风控中的多因素验证）、自动化运维（故障排查与修复流程）。</p><p><strong>优势与局限</strong>：ReAct 支持运行时动态调整策略，使 Agent 能够实时整合外部反馈。但由于频繁的推理-行动切换，每轮推理可能带来较高的延迟开销，不适合需要长时间规划的超大规模任务。</p><h3 id="_4-2-plan-and-execute-模式-结构化规划优先" tabindex="-1">4.2 Plan-and-Execute 模式：结构化规划优先 <a class="header-anchor" href="#_4-2-plan-and-execute-模式-结构化规划优先" aria-label="Permalink to &quot;4.2 Plan-and-Execute 模式：结构化规划优先&quot;">​</a></h3><p>Plan-and-Execute 模式由 LangChain 团队于 2023 年提出，其核心思想是“先全局规划、后分步执行”。该模式通过 LLM 生成完整任务计划，再按步骤执行并动态调整。</p><p><strong>架构设计</strong>：</p><ul><li><strong>Planner Agent（规划 Agent）</strong>：根据用户输入生成详细的任务规划和执行方案，将主任务分解为子任务，并生成依赖关系图。</li><li><strong>Execute Agent（执行 Agent）</strong>：依据规划内容执行具体任务。可包含多个专业执行者——Search Agent（网页信息搜索）、Shell Agent（执行终端命令/脚本）、Code Agent（编写/运行代码）、Assist Agent（信息整合与数据分析）、Report Agent（生成分析报告）等。</li><li><strong>Replanner（重规划者）</strong>：评估进度、检测异常并在必要时重新规划。</li></ul><p><strong>执行流程</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">用户输入 → Planner 生成任务规划 → 用户确认 → Executor 分步执行 → 完成/需要调整时触发 Replanner → 输出最终结果</span></span></code></pre></div><p>Plan-and-Execute 模式在 Tencent Cloud 等生产平台中已作为预置的多 Agent 协作模式实现，用户可直接使用已沉淀的 Agent 配置、记忆管理与多 Agent 协作的最佳实践。</p><p><strong>优势与局限</strong>：</p><ul><li><strong>优势</strong>：任务依赖关系清晰、执行过程可审计、适合长期复杂任务（如项目开发、科研实验、深度分析报告的撰写等）、具备错误恢复能力。</li><li><strong>局限</strong>：缺乏动态调整能力（在高度不确定的环境下可能失效），计划生成质量高度依赖 LLM 的能力，不适合对实时性要求极高的交互场景。</li></ul><p><strong>优化策略</strong>：分层规划（将大任务分解为子任务树）、里程碑检查点（在关键节点插入验证逻辑）、异常处理机制（当执行偏离计划时触发重规划）、计划质量评估。</p><h3 id="_4-3-reflection-模式-基于语言反馈的自我优化" tabindex="-1">4.3 Reflection 模式：基于语言反馈的自我优化 <a class="header-anchor" href="#_4-3-reflection-模式-基于语言反馈的自我优化" aria-label="Permalink to &quot;4.3 Reflection 模式：基于语言反馈的自我优化&quot;">​</a></h3><p>Reflection 模式通过语言反馈实现 Agent 能力的持续优化，避免传统强化学习中的权重更新开销。该模式突破了传统 RLHF 的局限，使 Agent 能够通过自然语言分析自身执行过程中的错误模式并提出改进建议。</p><p><strong>执行流程</strong>包括行动执行阶段（完成当前任务步骤）、反思阶段（LLM 生成自然语言反馈，如“此步骤效率低，建议改用 API”）、策略更新阶段（根据反馈调整后续行为逻辑）。</p><p>Reflection 模式特别适合需要持续优化的长期任务（如个性化推荐系统）和环境动态变化的场景（如自动驾驶），其核心价值在于：Agent 能够“从错误中学习”，无需人工介入即可实现策略的自我改进。</p><h3 id="_4-4-三种规划架构的核心差异" tabindex="-1">4.4 三种规划架构的核心差异 <a class="header-anchor" href="#_4-4-三种规划架构的核心差异" aria-label="Permalink to &quot;4.4 三种规划架构的核心差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>ReAct</th><th>Plan-and-Execute</th><th>Reflection</th></tr></thead><tbody><tr><td>决策单元</td><td>单步推理-行动循环</td><td>全局任务规划 + 分步执行</td><td>行动后反思优化</td></tr><tr><td>工具调用</td><td>动态触发（每轮推理后）</td><td>按计划顺序执行</td><td>根据反思动态调整</td></tr><tr><td>状态管理</td><td>依赖 LLM 内部状态</td><td>显式任务状态跟踪</td><td>结合内部状态与语言反馈</td></tr><tr><td>适用场景</td><td>实时动态交互</td><td>结构化长周期任务</td><td>持续优化型任务</td></tr><tr><td>延迟特性</td><td>中等（每轮推理开销）</td><td>较低（规划阶段一次性开销）</td><td>较高（反思阶段额外开销）</td></tr><tr><td>可扩展性</td><td>高</td><td>中等</td><td>高</td></tr></tbody></table><h2 id="五、分层规划与双层规划架构" tabindex="-1">五、分层规划与双层规划架构 <a class="header-anchor" href="#五、分层规划与双层规划架构" aria-label="Permalink to &quot;五、分层规划与双层规划架构&quot;">​</a></h2><h3 id="_5-1-分层任务规划的理论基础" tabindex="-1">5.1 分层任务规划的理论基础 <a class="header-anchor" href="#_5-1-分层任务规划的理论基础" aria-label="Permalink to &quot;5.1 分层任务规划的理论基础&quot;">​</a></h3><p>分层规划是一种“分而治之”的规划策略，其核心思想是将复杂任务分解为多个抽象层级，每个层级专注于不同粒度的规划问题。2026 年的主要技术创新集中在三个方向：动态自适应的层次构建、规划与执行的解耦、以及多 Agent 分层化组织。</p><h3 id="_5-2-reactree-动态构建的-agent-树" tabindex="-1">5.2 ReAcTree：动态构建的 Agent 树 <a class="header-anchor" href="#_5-2-reactree-动态构建的-agent-树" aria-label="Permalink to &quot;5.2 ReAcTree：动态构建的 Agent 树&quot;">​</a></h3><p>ReAcTree（Reason-Act Tree）提出了一种分层任务规划方法，通过动态构建的 Agent 树将复杂目标分解为可管理的子目标。</p><p><strong>核心设计</strong>：</p><ul><li><strong>动态 Agent 树构建</strong>：每个子目标由一个 LLM Agent 节点处理，该节点具备推理、行动和进一步扩展树的能力。控制流节点协调 Agent 节点的执行策略。</li><li><strong>双记忆系统整合</strong>：每个 Agent 节点从事例记忆（episodic memory）中检索目标特定的、子目标级别的示例，同时通过工作记忆（working memory）共享环境特定的观察结果。</li></ul><p><strong>性能突破</strong>：在 WA H-NL 基准上，ReAcTree 结合 Qwen 2.5 72B 模型实现了 61% 的目标成功率，几乎是 ReAct 单独执行的 31% 的两倍。这一结果表明，在需要长期视野的任务中，动态分层规划相比于单体循环推理具有显著优势。ReAcTree 已作为 Full Paper 被 AAMAS 2026 大会接收。</p><h3 id="_5-3-naviagent-图驱动的双层规划" tabindex="-1">5.3 NaviAgent：图驱动的双层规划 <a class="header-anchor" href="#_5-3-naviagent-图驱动的双层规划" aria-label="Permalink to &quot;5.3 NaviAgent：图驱动的双层规划&quot;">​</a></h3><p>NaviAgent 提出了一种显式的双层架构，通过基于图的工具关系建模，将任务规划与工具执行解耦。</p><p><strong>架构解析</strong>：规划层由 LLM 驱动的 Agent 决策是否直接响应、澄清意图或检索并执行工具链，完全不需关心工具间的复杂度。执行层通过 Tool World Navigation Model 编码工具间的结构关系和行为关系，引导 Agent 构建可扩展且鲁棒的调用序列。</p><p><strong>关键技术点</strong>：工具关系图编码了工具之间的依赖关系和调用模式；执行反馈使系统实现规划和执行之间的闭环对齐，支持在大型工具生态中的自适应导航。</p><p><strong>性能数据</strong>：在 API-Bank 和 ToolBench 上的评估显示，NaviAgent 在复杂任务上带来平均 13.1 个百分点的任务成功率提升。在跨 7 个领域的 50 个真实 API 测试中，实现了 4.3 到 12.0 个百分点的持续改进，步数和延迟均有减少。该工作已被 ICML 2026 大会接收。</p><h3 id="_5-4-adaplan-h-从粗到细的自适应分层规划" tabindex="-1">5.4 AdaPlan-H：从粗到细的自适应分层规划 <a class="header-anchor" href="#_5-4-adaplan-h-从粗到细的自适应分层规划" aria-label="Permalink to &quot;5.4 AdaPlan-H：从粗到细的自适应分层规划&quot;">​</a></h3><p>AdaPlan-H 从认知科学中的“渐进式细化”原则汲取灵感，提出了一种模仿人类规划策略的自适应分层规划机制。</p><p><strong>核心理念</strong>：从粗粒度的宏观计划出发，根据任务复杂性逐步细化。为不同难度的任务量身定制自适应的分层计划，并可进一步通过模仿学习和能力增强进行优化。</p><p><strong>关键能力</strong>：任务难度感知（根据任务复杂度动态调整细化程度），避免过度规划（简单任务不产生不必要的细节），消除规划不足（复杂任务获得足够的分解深度）。</p><h3 id="_5-5-三层分治-指挥官-调度官-执行者的层级架构" tabindex="-1">5.5 三层分治：指挥官-调度官-执行者的层级架构 <a class="header-anchor" href="#_5-5-三层分治-指挥官-调度官-执行者的层级架构" aria-label="Permalink to &quot;5.5 三层分治：指挥官-调度官-执行者的层级架构&quot;">​</a></h3><p>在多 Agent 规划架构中，最常见的生产级方案是指挥官-调度官-执行者的三层分治设计：</p><ul><li><strong>指挥官</strong>（Commander Agent）：系统的“大脑”，负责接收业务目标，将其转化为结构化任务体系，定义各 Agent 的职责边界与协作规则。对应思维链（CoT）和 ReAct 等推理范式。</li><li><strong>调度官</strong>（Orchestration Agent）：系统的“神经网络”，根据指挥官输出的任务结构进行调度，管理执行顺序、并发关系与资源分配。</li><li><strong>执行型 Agent</strong>（Worker Agents）：系统的“双手”，在明确授权下完成具体子任务，调用指定工具输出结果，不具备整体任务调整权。</li></ul><p>分层规划的核心优势在于三个层面的职责分离：规划层专注宏观决策与任务分解，执行层专注工具调用与结果产出，反馈层（Reflection 机制）负责持续优化。这一架构通过三层验证机制有效阻断了错误传播。</p><h2 id="六、动态重规划与反馈闭环" tabindex="-1">六、动态重规划与反馈闭环 <a class="header-anchor" href="#六、动态重规划与反馈闭环" aria-label="Permalink to &quot;六、动态重规划与反馈闭环&quot;">​</a></h2><h3 id="_6-1-规划-执行-验证-循环" tabindex="-1">6.1 “规划-执行-验证”循环 <a class="header-anchor" href="#_6-1-规划-执行-验证-循环" aria-label="Permalink to &quot;6.1 “规划-执行-验证”循环&quot;">​</a></h3><p>真正的智能规划不是一个一次性生成完整计划的过程，而是一个持续循环的动态系统。“规划-执行-验证”循环包含三个核心阶段：</p><ul><li><strong>规划阶段</strong>：生成初始任务计划，设定子任务依赖关系和执行顺序。</li><li><strong>执行阶段</strong>：按计划依次执行子任务，每次执行后更新状态。</li><li><strong>验证阶段</strong>：检查执行结果与预期是否一致，检测偏差来源并判断是否需要重新规划。</li></ul><p>当实际执行结果偏离原始计划时，系统触发重规划机制。2026 年的主流实现中，Replanner 负责评估进度、检测异常并重新规划，它协调 Planner、Executor 和自身三个核心角色，进行结构化任务、工具调用执行、进度评估和迭代重规划，直到用户目标达成。</p><h3 id="_6-2-关闭规划-执行缝隙" tabindex="-1">6.2 关闭规划-执行缝隙 <a class="header-anchor" href="#_6-2-关闭规划-执行缝隙" aria-label="Permalink to &quot;6.2 关闭规划-执行缝隙&quot;">​</a></h3><p>NaviAgent 的核心创新之一在于：它将来自真实工具交互的反馈纳入系统，实现规划与执行之间的闭环对齐，支持在大型工具生态中的自适应导航。这种闭环设计解决了传统规划系统中“计划是一回事，执行是另一回事”的根本性脱节问题。</p><p>在“规划-执行-验证”循环中，验证反馈不仅用于判断是否需要重规划，还可以被用来更新 Agent 的规划策略，使其在下一次遇到类似任务时能够做出更好的规划决策。这种持续学习的能力是实现 Agent 自主进化的关键。</p><h2 id="七、2025–2026-年前沿规划创新" tabindex="-1">七、2025–2026 年前沿规划创新 <a class="header-anchor" href="#七、2025–2026-年前沿规划创新" aria-label="Permalink to &quot;七、2025–2026 年前沿规划创新&quot;">​</a></h2><p>2025–2026 年间，Agent 规划技术迎来了多项重要学术突破，以下是最具代表性的研究成果。</p><h3 id="_7-1-rp-react-规划者-执行者分离架构" tabindex="-1">7.1 RP-ReAct：规划者-执行者分离架构 <a class="header-anchor" href="#_7-1-rp-react-规划者-执行者分离架构" aria-label="Permalink to &quot;7.1 RP-ReAct：规划者-执行者分离架构&quot;">​</a></h3><p>RP-ReAct（Reasoner Planner-ReAct）提出了一种新颖的多 Agent 方法，从根本上将战略规划与低级执行解耦，以实现更优的可靠性和效率。</p><p><strong>架构设计</strong>：由负责规划每个子步骤的 Reasoner Planner Agent（RPA）和将子步骤转化为具体工具调用的 Proxy-Execution Agent（PEA）组成。RPA 利用大推理模型（Large Reasoning Model）的强大推理能力持续分析执行结果，PEA 采用 ReAct 方法执行底层操作。</p><p><strong>工程创新——上下文保存策略</strong>：PEA 内置的上下文保存策略通过外部存储和按需访问来管理大型工具输出，有效缓解了上下文窗口溢出的问题。这对于必须使用本地开放权重模型（上下文窗口较小）的企业场景尤其关键。</p><p><strong>评估结果</strong>：在挑战性的多域 ToolQA 基准上，RP-ReAct 在多个评估域中均展现出优于现有基线的性能和更强的泛化能力。该研究同时确立了跨不同模型规模的鲁棒性和稳定性，为企业部署提供了可落地的智能体解决方案。</p><h3 id="_7-2-eaglet-全局规划器训练" tabindex="-1">7.2 EAGLET：全局规划器训练 <a class="header-anchor" href="#_7-2-eaglet-全局规划器训练" aria-label="Permalink to &quot;7.2 EAGLET：全局规划器训练&quot;">​</a></h3><p>EAGLET 是一种高效且有效的规划器训练方法，用于增强执行者 Agent 的规划能力而无需人工干预。其核心贡献在于：证明了可以通过自动化方式训练执行者 Agent 的规划能力，为规模化部署提供了路径。该方法特别适用于长期视野任务中因缺乏全局规划而出现的试错和幻觉生成问题。</p><h3 id="_7-3-pmc-多约束零样本规划" tabindex="-1">7.3 PMC：多约束零样本规划 <a class="header-anchor" href="#_7-3-pmc-多约束零样本规划" aria-label="Permalink to &quot;7.3 PMC：多约束零样本规划&quot;">​</a></h3><p>PMC（Planning with Multi-Constraints）是一种零样本方法，用于基于 LLM 的多 Agent 协作系统，通过将复杂任务规划分解为一系列层级化的子任务来简化带约束的规划问题。这一方法的核心价值在于：任务约束的分解和分配本身就是一种规划智慧，有助于解决真实企业场景中因多重约束（预算限制、时间窗口、资源可用性等）而导致的规划困难。</p><h3 id="_7-4-capa-开放式-agent-的能力约束规划" tabindex="-1">7.4 CAPA：开放式 Agent 的能力约束规划 <a class="header-anchor" href="#_7-4-capa-开放式-agent-的能力约束规划" aria-label="Permalink to &quot;7.4 CAPA：开放式 Agent 的能力约束规划&quot;">​</a></h3><p>2026 年 5 月发布的 CAPA（Capability-Constrained Planning）提出了一种新颖的规划框架，使 Agent 在规划过程中显式地考虑能力约束，确保生成的行动计划与 Agent 的实际执行能力相匹配。这项工作的核心洞察在于：很多规划失败的根源不在于推理不足，而在于规划者对自己“能做什么、不能做什么”缺乏清晰认知。</p><h3 id="_7-5-prosea-探索驱动的迭代规划进化" tabindex="-1">7.5 ProSEA：探索驱动的迭代规划进化 <a class="header-anchor" href="#_7-5-prosea-探索驱动的迭代规划进化" aria-label="Permalink to &quot;7.5 ProSEA：探索驱动的迭代规划进化&quot;">​</a></h3><p>ProSEA（Problem Solving via Exploration Agents）引入了一个模块化的多 Agent 框架，专为通过探索和计划进化进行迭代问题求解而设计。大多数现有 Agent 仍局限于静态规划和脆性交互，而 ProSEA 通过持续的探索机制使规划在执行中得以不断演化和完善。</p><h2 id="八、规划能力的评测基准" tabindex="-1">八、规划能力的评测基准 <a class="header-anchor" href="#八、规划能力的评测基准" aria-label="Permalink to &quot;八、规划能力的评测基准&quot;">​</a></h2><h3 id="_8-1-veritrip-面向旅行规划-agent-的可验证基准" tabindex="-1">8.1 VeriTrip：面向旅行规划 Agent 的可验证基准 <a class="header-anchor" href="#_8-1-veritrip-面向旅行规划-agent-的可验证基准" aria-label="Permalink to &quot;8.1 VeriTrip：面向旅行规划 Agent 的可验证基准&quot;">​</a></h3><p>VeriTrip 是一个用于旅行规划 Agent 的新型可验证基准测试平台。现有的基准测试大多围绕 API 为中心的范式构建，而 VeriTrip 为能够在无约束、多模态环境中运行的下一代规划 Agent 提供了严格的验证基础。这一方向的核心价值在于：真实世界中的规划问题无法通过预先定义的 API 完美建模，Agent 必须学会在非结构化的网络环境中灵活规划。</p><h3 id="_8-2-wah-nl-与-alfred-分层规划基准" tabindex="-1">8.2 WAH-NL 与 ALFRED：分层规划基准 <a class="header-anchor" href="#_8-2-wah-nl-与-alfred-分层规划基准" aria-label="Permalink to &quot;8.2 WAH-NL 与 ALFRED：分层规划基准&quot;">​</a></h3><p>WAH-NL（WebSHOP 的文本版本）和 ALFRED 是评估分层规划效果的两个经典基准。ReAcTree 正是通过在这两个基准上的测试，证明了动态 Agent 树架构相比 ReAct 的显著优势。</p><h3 id="_8-3-toolqa-多域工具集成规划" tabindex="-1">8.3 ToolQA：多域工具集成规划 <a class="header-anchor" href="#_8-3-toolqa-多域工具集成规划" aria-label="Permalink to &quot;8.3 ToolQA：多域工具集成规划&quot;">​</a></h3><p>ToolQA 专注于评估 Agent 在跨多域复杂任务中的工具集成与规划能力，RP-ReAct 在此基准上的评估确立了跨模型规模的鲁棒性和稳定性。</p><h2 id="九、规划能力的开放挑战" tabindex="-1">九、规划能力的开放挑战 <a class="header-anchor" href="#九、规划能力的开放挑战" aria-label="Permalink to &quot;九、规划能力的开放挑战&quot;">​</a></h2><h3 id="_9-1-长期视野中的试错与幻觉" tabindex="-1">9.1 长期视野中的试错与幻觉 <a class="header-anchor" href="#_9-1-长期视野中的试错与幻觉" aria-label="Permalink to &quot;9.1 长期视野中的试错与幻觉&quot;">​</a></h3><p>在长期视野任务中，缺乏全局规划是 Agent 产生试错行为和幻觉行动的核心原因。即使是最先进的模型，在需要跨越数十个步骤的任务中也常常迷失方向。</p><h3 id="_9-2-约束下的复杂规划" tabindex="-1">9.2 约束下的复杂规划 <a class="header-anchor" href="#_9-2-约束下的复杂规划" aria-label="Permalink to &quot;9.2 约束下的复杂规划&quot;">​</a></h3><p>企业真实场景中的规划往往伴随着多重、动态变化的约束条件（预算、时间、资源、权限等）。如何使 Agent 在约束下做出最优规划决策，仍是有待解决的挑战。</p><h3 id="_9-3-规划的可解释性与可验证性" tabindex="-1">9.3 规划的可解释性与可验证性 <a class="header-anchor" href="#_9-3-规划的可解释性与可验证性" aria-label="Permalink to &quot;9.3 规划的可解释性与可验证性&quot;">​</a></h3><p>随着 Agent 规划能力的增强，其决策过程的可解释性变得越来越重要。在高风险场景（如金融风控、医疗诊断）中，规划链路必须完全可追溯、可审计、可验证。</p><h3 id="_9-4-动态环境中的规划适应性" tabindex="-1">9.4 动态环境中的规划适应性 <a class="header-anchor" href="#_9-4-动态环境中的规划适应性" aria-label="Permalink to &quot;9.4 动态环境中的规划适应性&quot;">​</a></h3><p>Agent 规划不是在真空中进行的，而是在动态变化的环境中执行的。当环境条件（如 API 响应延迟、数据可用性）实时变化时，Agent 需要具备在线调整规划的能力。</p><h3 id="_9-5-规划与执行的闭环对齐" tabindex="-1">9.5 规划与执行的闭环对齐 <a class="header-anchor" href="#_9-5-规划与执行的闭环对齐" aria-label="Permalink to &quot;9.5 规划与执行的闭环对齐&quot;">​</a></h3><p>“计划是一回事，执行是另一回事”——规划与执行之间的缝隙是导致任务失败的常见原因。如何建立有效的反馈机制，使执行结果能够及时影响后续规划决策，是当前仍需持续投入的研究方向。</p><h3 id="_9-6-计算效率与规划深度的平衡" tabindex="-1">9.6 计算效率与规划深度的平衡 <a class="header-anchor" href="#_9-6-计算效率与规划深度的平衡" aria-label="Permalink to &quot;9.6 计算效率与规划深度的平衡&quot;">​</a></h3><p>分层规划和多步推理带来了计算开销与规划精度的权衡。如何在保持高规划质量的同时控制 token 消耗和推理延迟，是生产环境中的核心工程挑战。</p><h2 id="十、未来演进方向" tabindex="-1">十、未来演进方向 <a class="header-anchor" href="#十、未来演进方向" aria-label="Permalink to &quot;十、未来演进方向&quot;">​</a></h2><h3 id="_10-1-从静态规划到动态自适应" tabindex="-1">10.1 从静态规划到动态自适应 <a class="header-anchor" href="#_10-1-从静态规划到动态自适应" aria-label="Permalink to &quot;10.1 从静态规划到动态自适应&quot;">​</a></h3><p>从 ReAcTree 的 61% 成功率相比 ReAct 的 31% 翻倍增长来看，规划能力正在从固定流程走向动态自适应。未来的 Agent 将能够在执行中持续感知环境变化并动态调整规划策略。</p><h3 id="_10-2-从单-agent-规划到多-agent-协同规划" tabindex="-1">10.2 从单 Agent 规划到多 Agent 协同规划 <a class="header-anchor" href="#_10-2-从单-agent-规划到多-agent-协同规划" aria-label="Permalink to &quot;10.2 从单 Agent 规划到多 Agent 协同规划&quot;">​</a></h3><p>随着多 Agent 架构的成熟，规划将不再是单一 Agent 的孤立决策，而是多个专业化 Agent 之间协同完成的任务。一个 Agent 负责宏观战略规划，多个专业 Agent 负责战术层面规划和执行分工，规划智能体的上层设计正在成为新趋势。</p><h3 id="_10-3-从-llm-驱动到混合规划引擎" tabindex="-1">10.3 从 LLM 驱动到混合规划引擎 <a class="header-anchor" href="#_10-3-从-llm-驱动到混合规划引擎" aria-label="Permalink to &quot;10.3 从 LLM 驱动到混合规划引擎&quot;">​</a></h3><p>LLM 在开放式任务中展现出卓越的语义理解能力，但在逻辑推理和约束满足方面仍存在局限。未来规划架构将采用混合引擎——用 LLM 处理高层次自然语言理解与抽象规划，用符号求解器处理确定性逻辑和约束求解，用 RL 策略处理重复性决策。这可以类比于“LLM 负责写大纲，符号求解器负责验证大纲的可行性，RL 策略负责执行细节”。Anthropic、Google 和 OpenAI 在 2026 年均已对该方向有不同程度的投入。</p><h3 id="_10-4-规划能力的持续学习与自我进化" tabindex="-1">10.4 规划能力的持续学习与自我进化 <a class="header-anchor" href="#_10-4-规划能力的持续学习与自我进化" aria-label="Permalink to &quot;10.4 规划能力的持续学习与自我进化&quot;">​</a></h3><p>从 Agents of Change 等工作的探索来看，Agent 规划能力将不再依赖静态提示工程，而是通过与环境的持续交互和基于工件的持续学习，从脆弱的逐步决策者进化为稳定的策略设计者。</p><h2 id="十一、总结" tabindex="-1">十一、总结 <a class="header-anchor" href="#十一、总结" aria-label="Permalink to &quot;十一、总结&quot;">​</a></h2><p>本笔记系统梳理了 AI Agent 规划能力的核心知识体系，归纳要点如下：</p><ol><li><p><strong>基本概念</strong>：规划能力是 Agent 将抽象目标转化为可执行行动序列的核心认知机制。规划层在“感知-规划-行动”闭环架构中承担从目标到策略转化的关键职责。</p></li><li><p><strong>推理范式</strong>：CoT（线性推理）→ ToT（分支推理）→ GoT（图推理）构成了推理能力的三级跃迁。CoT 在数学推理中提升 37% 准确率；ToT 使代码生成正确率从 61% 提升至 78%；GoT 通过图结构实现更灵活的多路径推理与结果聚合。</p></li><li><p><strong>核心架构</strong>：三种规划架构各具特色——ReAct 适合实时动态交互（推理-行动闭环）、Plan-and-Execute 适合结构化长周期任务（先规划后执行）、Reflection 适合持续优化场景（行动后反思迭代）。</p></li><li><p><strong>分层规划</strong>：ReAcTree 通过动态构建 Agent 树实现分层规划，在 WAH-NL 上达到 61% 成功率，对比 ReAct 几乎翻倍；NaviAgent 以双层架构在图驱动下实现平均 13.1 个百分点的 TSR 提升，已被 ICML 2026 接收；AdaPlan-H 以自适应机制平衡过度规划与规划不足。</p></li><li><p><strong>动态重规划</strong>：“规划-执行-验证-重规划”闭环使 Agent 能够根据执行反馈动态调整原计划。验证反馈不仅用于重规划触发，还可用于持续优化规划策略。</p></li><li><p><strong>前沿创新</strong>：RP-ReAct 实现了规划与执行的完全解耦，解决局部模型上下文窗口限制的企业部署问题；EAGLET 开创了无需人工干预的规划器训练新范式；PMC 支持多约束零样本场景下的层级化规划。</p></li><li><p><strong>开放挑战</strong>：长期视野中的试错与幻觉、多约束下的最优规划、规划可解释性与可验证性、动态环境中的适应性、规划与执行的闭环对齐、效率与精度的平衡是当前的核心挑战。</p></li><li><p><strong>未来方向</strong>：从静态到动态自适应、从单 Agent 到多 Agent 协同规划、从纯 LLM 驱动到混合规划引擎、从静态提示到持续学习与自我进化，构成了规划能力的未来演进路径。</p></li></ol><p>规划能力正在从 Agent 技术的“附属能力”成长为决定 Agent 智能化水平的“核心支柱”。从 ReAcTree 到 RP-ReAct 再到 NaviAgent，每一篇 2025–2026 年的顶会论文都在向同一个方向推进：让 AI Agent 拥有更可靠、更高效、更自适应的规划大脑。理解规划机制的设计权衡与实现细节，已成为构建真正自主智能体的关键技能。</p>`,136)])])}const _=t(o,[["render",i]]);export{c as __pageData,_ as default};
